SET search_path TO lms, extensions;

-- ============================================================
-- Fix: Make handle_new_user trigger robust against nulls and
-- duplicate inserts. Also add INSERT policy so the trigger can
-- always write, regardless of RLS.
-- ============================================================

-- 1. Replace the trigger function with a hardened version
CREATE OR REPLACE FUNCTION lms.handle_new_user()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER
SET search_path = lms
AS $$
BEGIN
  -- Guard: skip if email is null (shouldn't happen, but be safe)
  IF NEW.email IS NULL THEN
    RETURN NEW;
  END IF;

  INSERT INTO lms.users (id, email, full_name, role)
  VALUES (
    NEW.id,
    NEW.email,
    COALESCE(NEW.raw_user_meta_data->>'full_name', NULL),
    COALESCE(NEW.raw_user_meta_data->>'role', 'learner')
  )
  ON CONFLICT (id) DO NOTHING;  -- idempotent: safe to run twice

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Log the error but do NOT fail the auth user creation
  RAISE WARNING 'handle_new_user failed for user %: %', NEW.id, SQLERRM;
  RETURN NEW;
END;
$$;

-- 2. Ensure the trigger exists (recreate if missing)
DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;
CREATE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE PROCEDURE lms.handle_new_user();
